import pandas as pd
import json
import ast

# List all source file paths
source_files = [
    "autopipeline-benchmarks/github-pipelines/length9_16/test_0.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_1.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_2.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_3.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_4.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_5.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_6.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_7.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_8.csv",
]

# Read all source files into a list of DataFrames with index_col=0 to ignore numerical index column
dfs = [pd.read_csv(f, index_col=0) for f in source_files]

# Concatenate all source DataFrames vertically (union)
df_all = pd.concat(dfs, ignore_index=True)

# Function to format 'hashtags' column to string representation matching target examples
def format_hashtags(h):
    if pd.isna(h):
        return '[]'
    if isinstance(h, list):
        if len(h) == 0:
            return '[]'
        # Convert list of dicts or strings to string with double quotes
        return str(h).replace("'", '"')
    if isinstance(h, str):
        h = h.strip()
        if h == '[]':
            return '[]'
        # Try to parse string representation of list/dicts and convert to string with double quotes
        try:
            parsed = json.loads(h.replace("'", '"'))
            if isinstance(parsed, list):
                return str(parsed).replace("'", '"')
            else:
                return h
        except Exception:
            # If parsing fails, return as is
            return h
    return str(h)

df_all['hashtags'] = df_all['hashtags'].apply(format_hashtags)

# Function to format 'coordinates' column to string JSON with double quotes or 'NaN' string
def format_coordinates(c):
    if pd.isna(c):
        return 'NaN'  # Target examples show NaN as string "NaN"
    if isinstance(c, dict):
        return json.dumps(c)
    if isinstance(c, str):
        c = c.strip()
        try:
            d = ast.literal_eval(c)
            if isinstance(d, dict):
                return json.dumps(d)
            else:
                return c
        except Exception:
            return c
    return str(c)

df_all['coordinates'] = df_all['coordinates'].apply(format_coordinates)

# Ensure 'created_at' and 'text' columns are strings
df_all['created_at'] = df_all['created_at'].astype(str)
df_all['text'] = df_all['text'].astype(str)

# Final DataFrame matches target schema and data distribution, no aggregation or group by needed

# Write the final DataFrame to the target CSV file
df_all.to_csv(
    "autopipeline-benchmarks/github-pipelines/length9_16/target_multisource_critique_history.csv",
    index=False,
)
